quests[75633] = { id = 75633, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have the Technology", description = "During our... long discussion about how to find Tyr's disc, Chromie and I agreed that you were the right person to help us, {name}. But finding the location of Tyr's disc could be very dangerous and would likely require more than just your help.\n\nWhile I work here to narrow down what we need to find the disc, Chromie can give you more details.", completion = "It's good to see you again, {name}! I have hope that this time we will finally be able to restore Tyr's memories.", objectives = "Ask Chromie about the plan to recover Tyr's memory disc.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75634] = { id = 75634, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reforging the Tyr's Guard", description = "After the tomb was destroyed and the Silver Scale failed to bring Tyr back, I made the decision to rededicate my life to Tyr.\n\nAnd I made the even harder decision to leave the past behind and reforge Tyr's Guard.\n\nI had faith Tyr would need me again soon. And, after consulting with the Silver Hand, Koranos and I believe we have found four worthy Tyr's Guard recruits.\n\nCome with me to Brackenhide Hollow, and assist me in their final training. Then we can venture into the timeways to find Tyr's disc.", completion = "Now that you're here, we can get started with my recruits' final trials.", objectives = "Meet Travard at the Tyr's Guard camp in Brackenhide Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75635] = { id = 75635, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "For Tyr!", description = "Did they all complete their trials successfully? Good. I'm sure you played no small part in that.\n\nThere's one final step we need to take before I can formally induct our recruits as full-fledged members of the Tyr's Guard: the Tyr's Guard initiation ceremony. \n\nIt would make me proud if you stood with us on the steps of Tyrhold as I formally reforge the Tyr's Guard. Will you join us?", completion = "The Tyr's Guard stands once again. I feel both renewed and... very old. They still have much to learn, and I have much to teach them.\n\nNow, onto the task of recovering Tyr's memories!", objectives = "Witness the induction ceremony of the Tyr's Guard on the steps of Tyrhold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75636] = { id = 75636, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tyrangulation", description = "The portals are ready. The sooner your team deploys those beacons, the sooner we can get the location of the disc. \n\nHow you deploy your forces is up to you--and Travard.", completion = "Welcome back! Eternus said there was a signal from your beacon, so I assume everything went smoothly?", objectives = "Protect Travard at the Temple of Order.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75637] = { id = 75637, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Final Beacon", description = "Valunei and Talthis still aren't back. They must have had trouble with their beacon. We can't find the disc without it, and there's no way to help from here. \n\nWe must lead the Tyr's Guard through their portal to help. Are you ready, {name}?", progress = "We must discover what was happened.", completion = "We're all back in one piece, thank the Light.\n\nNow, hopefully our dragon friends can find that disc!", objectives = "Help the Tyr's Guard activate the Final Beacon.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75638] = { id = 75638, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dislocated Disc Located", description = "We were successful, {name}, but we barely made it back from our battle with the Black Empire.\n\nEternus is still divining the location of the disc, and while she does, I'd like to ask a favor.\n\nI have unwavering faith in my recruits, but...\n\nI am worried about Valunei. I would speak to her, but I don't want it to appear as though I think she has failed us. Talk to her and make sure she's all right.\n\nIt may also be a good idea to check in with the rest of Tyr's Guard as well.", progress = "I'm worried about my recruits, but maybe I should be worried about myself.\n\nReforming the Tyr's Guard has been a kind of catharsis. But I'm worried that it may be too much so.\n\nI was devastated by the loss of my comrades in the Tyr's Guard... I worry that I may be pushing them too hard.\n\nOr myself. I've been at this a long time, {name}. But to see Tyr alive once more... that gives me purpose.\n\nI just hope wisdom comes with my age, and I do right by my new recruits. And that they all come home.", completion = "I'm glad to hear you were able to speak to her. It sounds like she is ready despite what happened. \n\nA lesser person would have not been able to pick themselves up after that, but Valunei is stronger than many of us realize.\n\nAs soon as Eternus locates the disc, we will be ready.", objectives = "Check in with the Tyr's Guard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75639] = { id = 75639, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fel Suspicions", completion = "The gate is warm to the touch.", objectives = "Spy on Madam Shadow and Assistant Phineas in the Darkmoon Faire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75640] = { id = 75640, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Azure Span flame.", objectives = "Honor the Midsummer Bonfire in the Azure Span", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75641] = { id = 75641, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Unified", description = "Fortune has favored our exploration, {name}! We have discovered something that may prove useful to you.\n\nIt is half of a Spark of Shadowflame. It's unfortunately just a shard and not powerful on its own, but should you locate the other piece and unite them, the spark could serve as a powerful reagent in your craft work.\n\nFind another Splintered Spark of Shadowflame. Unite both pieces to unlock their full potential.", progress = "Did you find the other half of the spark?", completion = "Excellent! If you find other splintered sparks, combine them to enhance your craft work!", objectives = "Find another Splintered Spark of Shadowflame.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75643] = { id = 75643, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orientation: Loamm Niffen", description = "I'm impressed. Elder Honeypelt speaks highly of you--and that's rare!\n\nYour friends Ebyssian and Emberthal admittedly made similar impressions with us after we caught their scent. They told me of your hunt for the fiery monster that's invaded Zaralek from the uplands. A worthy reason to become allies.\n\nBut we'll need a bit more time to discuss it. Why not take a short break to meet with my people. Trade, leisure, travel--there's no shortage of ways to spend your time here in Loamm!", progress = "Smells around every corner, but nothing dangerous!", completion = "Zaralek Cavern will not see the end of these new enemies any time soon, so let us continue getting to know each other with open arms and open snouts.\n\nConsider this your official invitation to stay with us here in Loamm, the great city of smells!", objectives = "Meet the Flight Master in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75644] = { id = 75644, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Six Hundred Feet Under", description = "That was just a taste of the niffen lifestyle. There's still far more to Loamm and even more from Zaralek Cavern. Continue exploring while you pursue the fiery monster, and let its scents continue to amaze you!\n\nFor now, Ebyssian asked that I send you his way. Seems your companions are planning what to do next.", progress = "There is much to discuss.", completion = "Though I still wish you had waited for Emberthal and myself to arrive, I do not believe the outcome would have been any different. This Incarnate is more powerful that we anticipated.\n\nThere is much to consider.", objectives = "Discuss the next plan of action with Ebyssian.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75645] = { id = 75645, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Thaldraszus flame.", objectives = "Honor the Midsummer Bonfire in Thaldraszus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75647] = { id = 75647, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Forbidden Reach flame.", objectives = "Honor the Midsummer Bonfire in the Forbidden Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75650] = { id = 75650, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor the Flame", description = "The Midsummer Fire Festival is a time to honor the elements.  The element of fire stirs passion within us all.  Many times, that passion pours out into aggressive actions.  But here, in this land, we focus our passion on reverence.\n\nWe will honor the flame as tradition dictates.  Will you honor the flame with us, {name}?", completion = "Honor the Zaralek Cavern flame.", objectives = "Honor the Midsummer Bonfire in Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75657] = { id = 75657, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time-Lost Trio", description = "We have a teensy problem I could use your help with. But it's... complicated.\n\nSome time ago, King Varian Wrynn was in a gladiator trio with Broll Bearmantle and Valeera Sanguinar. Those three just showed up in this 'Field of Ferocity' place and they're not only taking on all challengers, they're beating them too! They won't return through our portals until they lose.\n\nDo you think you could find some friends and defeat them? We'll be able to convince them to go back if you can, I'm sure of it!", progress = "You need to speak with Gurgthock to start the round, then defeat the time-lost gladiators.", completion = "Huh. I didn't know we had a group like that on the schedule. Or sparkly gold pyrotechnics.\n\nBut, I guess you won, so here.", objectives = "Defeat Valeera, Broll, and Lo'Gosh.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75660] = { id = 75660, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending Their Watch" }
quests[75661] = { id = 75661, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Curative Crystalline Collection" }
quests[75662] = { id = 75662, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Race to the Finish", description = "You look like someone that enjoys a good snail race! \n\nAnd what makes a snail race good you ask? Each snail must have a chance to win! \n\nAnd sometimes the snails might need a little bit of help. \n\nIf you grab a bag of treats from the chef and toss it in their path that'll get them moving. \n\nHow about we give Bashful a nudge to victory?", progress = "Has your snail won the race?", completion = "That was a great victory. I think you should be Bashful's new trainer!", objectives = "Help Bashful win a race.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75663] = { id = 75663, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Restless Torment" }
quests[75664] = { id = 75664, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Discordant Crystals" }
quests[75665] = { id = 75665, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Ally: Loamm Niffen", description = "Djaradin, dracthyr, and dragons! Oh my!  You can't help but smell the danger in these here caverns. We sure could use some armed assistance.\n\nYou scratch my back, and I'll make sure the kith scratch yours! We got loads of good stuff... for the right clientele.\n\nHow about it? Get out there and bury the competition?", progress = "Are our enemies six feet under?", completion = "You're that much closer to getting a whiff of the good stuff. \n\nThanks, champ.", objectives = "Aid the niffen and their allies throughout Zaralek Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75667] = { id = 75667, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Candy Bucket", objectives = "Candy buckets like this are located in inns throughout the realms. Go ahead... take some!", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
