quests[75694] = { id = 75694, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aberrus, the Shadowed Crucible: Sarkareth", description = "I have no interest in following my brothers within Aberrus, but I continue to care for their safety. Neltharion fell so deeply into madness that his secret stronghold is no doubt filled with any number of unspeakable dangers.\n\nGo with them, {name}. Stand with them. They will need your support in what is to come.", progress = "Aberrus holds mysteries and dangers alike. They must be dealt with, before any of them fall into the wrong hands.", completion = "I never imagined that Sarkareth would have gone to such lengths to seize power.\n\nThank you, {name}.", objectives = "Enter Aberrus, the Shadowed Crucible, and defeat Sarkareth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
