quests[75706] = { id = 75706, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Race to the Finish", description = "Everyone loves a good snail race! In the most exciting races, every snail has a chance to win.\n\nYou can help a snail win by giving it treats. Watch how fast it makes them go!\n\nGrab a bag of treats and toss them in the path of the snails. See if you can get Tricky to win!", progress = "Has your snail won the race?", completion = "That was a great victory. I think you should be Tricky's new trainer!", objectives = "Help Tricky win a race.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75707] = { id = 75707, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Race to the Finish", description = "Everyone loves a good snail race! In the most exciting races, every snail has a chance to win.\n\nYou can help a snail win by giving it treats. Watch how fast it makes them go!\n\nGrab a bag of treats and toss them in the path of the snails. See if you can get Brulee to win!", progress = "Has your snail won the race?", completion = "That was a great victory. I think you should be Brulee's new trainer!", objectives = "Help Brulee win a race.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75709] = { id = 75709, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find a Rumble Coin", description = "To use this game machine, you need a Rumble Coin.\n\nThere are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later.\n\nI stashed one coin here at the docks. If you find it, it's all yours, pal.\n\nInsert that Rumble Coin into the Rumble machine and watch the fun begin!", progress = "<The Warcraft Rumble machine stands before you. A small sign reads:>\n\nInsert Rumble Coin to play.", completion = "<As you insert your coin, the fun little machine rumbles and jingles.\n\nYou got a prize!>", objectives = "Find a Rumble Coin in Stormwind Harbor and insert it into the Warcraft Rumble machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75711] = { id = 75711, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Find a Rumble Coin", description = "To use this game machine, you need a Rumble Coin.\n\nThere are a bunch of coins hidden all around the Dragon Isles. We'll chat about those later.\n\nI stashed one coin over in the inn. If you find it, it's all yours, pal.\n\nInsert that Rumble Coin into the Rumble machine and watch the fun begin!", progress = "<The Warcraft Rumble machine stands before you. A small sign reads:>\n\nInsert Rumble Coin to play.", completion = "<As you insert your coin, the fun little machine rumbles and jingles.\n\nYou got a prize!>", objectives = "Find a Rumble Coin in the Broken Tusk and insert it into the Warcraft Rumble machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75712] = { id = 75712, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warcraft Rumble Minis: New Look!", description = "<You find a message etched into the foil.>\n\nThis Rumble Foil can be used at a Warcraft Rumble machine. Go and get a new look for one of your minis!", completion = "<The Warcraft Rumble machine has a hatch. It's the perfect size to insert a miniature toy and a Rumble Foil.>", objectives = "Go to the Warcraft Rumble machine in Stormwind Harbor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75713] = { id = 75713, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Warcraft Rumble Minis: New Look!", description = "<You find a message etched into the foil.>\n\nThis Rumble Foil can be used at a Warcraft Rumble machine. Go and get a new look for one of your minis!", completion = "<The Warcraft Rumble machine has a hatch. It's the perfect size to insert a miniature toy and a Rumble Foil.>", objectives = "Go to the Warcraft Rumble machine in Orgrimmar's Valley of Strength.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75720] = { id = 75720, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Care to Barter?", description = "Hey, Uplander!\n\nI hear you like helping. Maybe you could help me out? \n\nI need some packages sent to Valdrakken. If you don't peek and don't ask, I can make it worthwhile. \n\nStop by when you're in Loamm. We can work out a deal!\n\nYour new friend, Ponzo.", completion = "I can smell my letter on you. Ready to help?", objectives = "Talk to Ponzo in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75721] = { id = 75721, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartering 101", description = "So here's what I need you to do. \n\nA friend of mine, Kayann, went all the way up to Valdrakken. He's expecting a delivery from me. Can you get it to him? \n\nNo questions, though. Don't look, don't smell, don't taste. This is for Kayann's nose only!\n\nIf that's all right with you, I'll send you on your way--with my thanks, of course!", completion = "I know a Ponzo box when I smell a Ponzo box!\n\nThanks for bringing it up--quite the trip! Here's something Ponzo will love to trade for.", objectives = "Deliver Ponzo's box to Kayann in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75722] = { id = 75722, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bag of Gold", completion = "You'll always have our thanks!", objectives = "Talk to Mimuup in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75723] = { id = 75723, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cavern Drakewatching", description = "Well hey there, Uplander!\n\nWord is, you've been helping us out a lot! We got a little something for you in return. See me in Loamm and I'll hand it over!\n\nBest, \nHarlowe Marl", completion = "We're lucky to have you around!", objectives = "Talk to Harlowe Marl in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75724] = { id = 75724, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like the Niffen Do", completion = "Just put these mitts on, get them in the dirt, open your snout and boom!\n\nLoamm can be smelled from anywhere in Zaralek Cavern. \n\nThe secret's in the claws! It's always been in the claws!", objectives = "Talk to Mimuup in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75725] = { id = 75725, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Off to the Track", description = "Hey Champ! \n\nWe got a fresh golden opportunity for you. Snail racing! One of the most dynamic sports in the games! \n\nPonzo said you'd be interested. Called you a real go-getter!\n\nSo go! Get to the track in Glimmerogg! \n\nSee ya there, \nBriggul", completion = "You're here! Now all we need to do is... train our snail!", objectives = "Talk to Briggul in Glimmerogg.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75726] = { id = 75726, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sweaty Armor", description = "Well hey there, friend! \n\nWord is starting to spread about your continued support! We found some armor that might help you out, in thanks for all your troubles. \n\nMake sure to swing by Loamm so we can get you situated. \n\nBest, \nHarlowe Marl", sourceObjective = "Talk to Harlowe Marl in Loamm.", sourceObjectiveStatus = "unverified-source-field" }
quests[75727] = { id = 75727, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Smelliest Tabard", completion = "Here it is, handcrafted and handscented!", objectives = "Talk to Mimuup in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75728] = { id = 75728, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bartering Boulders", description = "Oh hey, Uplander! I could use your help again. \n\nI like your battering style. But you know these bricks? They're useless! Boulders are where it's at! \n\nCome see me in Loamm, and I'll give you all the details.\n\nPonzo", completion = "I hope you've been working out. These aren't light at all!", objectives = "Talk to Ponzo in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75729] = { id = 75729, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Attune to the Observer", description = "Can you believe this used to be an observatory? Our records indicate that the dragonkin here were mapping heavenly bodies in an attempt to predict the future.\n\nHow do you think they did it?\n\nI'm picking up a partial signature that matches the time window we're shooting for. Put on the Technoscryers and try to pinpoint the sources so we can dial it in.", progress = "Without those attunement relics we won't be able to solve this mystery, {name}.", completion = "Ah ha! Give me your scryers, so I can calibrate them.", objectives = "Technoscry for the three attunement relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75730] = { id = 75730, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slitherdrake Watching", description = "Well hello there!\n\nWord around here is that we've got your continued support--so we got a little something for you. Meet me in Loamm so I can hand it over!\n\nBest,\nHarlowe Marl", completion = "We're lucky to have you around!", objectives = "Talk to Harlowe Marl in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75731] = { id = 75731, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Scented Boots", description = "Well hello there!\n\nWord gets around of your continued support. We've found some armor that you may be able to use. Come meet me in Loamm and we'll see if it's useful!\n\nBest,\nHarlowe Marl", completion = "We're lucky to have ya around.", objectives = "Talk to Harlowe Marl in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75741] = { id = 75741, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bundle of Boulders", description = "Hey Uplander!\n\nI heard you've been telling people I've been mean to you. \n\nI haven't, but they told me to be nicer to you because all you've done for us. \n\nTaken advantage of? More like giving you some honest work!\n\nTo make you and the others happy, I'll give you some boulders. \n\nSee me in Loamm, \nPonzo", completion = "Make sure to mention to Mimuup that I was nice to you, you hear?", objectives = "Talk to Ponzo in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75742] = { id = 75742, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drake Helms", description = "Howdy!\n\nWord gets around of your continued support. \n\nWe got a little something for ya. Meet me in Loamm so I can get it to ya!\n\nBest,\nHarlowe Marl", completion = "We're lucky to have ya around.", objectives = "Talk to Harlowe Marl in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75744] = { id = 75744, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Token of Our Gratitude", description = "Greetings!\n\nWith all the help you've given us, we've decided it's only fair to return the favor.\n\nMeet me in Loamm. We have a reward we're eager to give you.\n\nSincerely,\nMimuup", completion = "Thanks for everything, Uplander!", objectives = "Talk to Mimuup in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75750] = { id = 75750, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Are They Not Beautiful?", objectives = "Defeat Shinmura in a Pet Battle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75765] = { id = 75765, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liquid Art", description = "<A clay pot filled with... mud?\n\nIt appears to be niffen in origin. Perhaps a resident of Loamm is looking for it!>", progress = "Oh, is that...?", completion = "You found my favorite slip pot!\n\nI can make slip in any pot, but this is one of the first pots I made of special sediments I dug myself.\n\nIt's sentimental ... AND sedimental!", objectives = "Return the Dripping Clay Pot to its owner in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75766] = { id = 75766, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruby in the Rough", description = "<A beautiful ruby set in fine gold sits nestled in a box of draconic origin.\n\nThe jewelcrafter in Loamm would love to take a look at this.>", progress = "It's SO shiny!!", completion = "This is beautiful! Did the dragons make this? It's so red and sparkly!\n\nThank you, {name}!", objectives = "Deliver the Shimmering Draconic Gem to Fanilly in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75767] = { id = 75767, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Good Time Boy", description = "<A very wet gorloc totem rests on the cave floor. How did this even get here?\n\nThe niffen love stuff like this. Maybe someone in Loamm will take it off your hands.>", progress = "I've needed a backup dancer!", completion = "<The niffen gives the totem a huge sniff.>\n\nHe smells like fish! Excellent! \n\nHe'll make an excellent bouncer for my shows. I think I'll call him... Whistlee!", objectives = "Find a new home for the Soaked Totem in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75768] = { id = 75768, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lucky Ducky", description = "<You find a small toy duckling.\n\nIt reminds you just a little of Loamm's swallows. Maybe Cinnam will like this?>", progress = "This is for me?", completion = "Wow! Thank you, {name}.\n\nSeeing as I'm the new Head Swallowsminder, I've been in need of an apprentice!", objectives = "Give the Feathered Friend to Cinnam in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75769] = { id = 75769, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drawing a Blank", description = "<A discarded painting covered in dust rests on the cave floor.\n\nMaybe someone in Loamm could make use of this?>", progress = "How did you know I wanted to try my nose at scent-painting?", completion = "A brand-new canvas! This will be perfect to practice my scent-painting on.\n\nRight now it smells so... blank! Thanks!", objectives = "Give the Stretched Canvas to a niffen in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75770] = { id = 75770, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Glass of Bubbly", description = "<You find a glowing blue potion of indeterminate origin.\n\nMaybe the Loamm alchemist will want to take a look?>", progress = "Hmm... I'll need to run some analysis!", completion = "This is most intriguing.\n\nI'll have to get the best noses in Loamm on the case so we can identify just what this is.\n\nThank you, {name}!", objectives = "Take the Bubbling Elixir to Mistie in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75771] = { id = 75771, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Incense Replay", description = "<You find some incense that smells familiar, but you can't quite place it.\n\nCitros will definitely want to take a sniff.>", progress = "Boy howdy! That's some mighty strong incense!", completion = "This doesn't smell like niffen!\n\nIt doesn't smell bad, though, not at all!\n\nIf you don't mind, could I take a closer sniff?", objectives = "Take the Mysterious Incense to Citros in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75772] = { id = 75772, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flask Manager", description = "<A small leather-wrapped flask sits on a shelf in the cave.\n\nSomeone might be missing this.>", progress = "Well it's not mine, but I'll take it off your hands!", completion = "There's no way this belonged to someone in Loamm. I've never seen leather quite like this before.\n\nIf you don't mind me asking, could I take a closer sniff at this? I might be able to apply some of these techniques!", objectives = "Find the owner of the leather-wrapped flask.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75773] = { id = 75773, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Little Blank Book", description = "<You find a book filled with Draconic text and not much else.\n\nMaybe someone in Loamm could help you decipher it?>", progress = "What do you mean, read it? It's blank, silly!", completion = "There's no writing in here! It just smells like blank paper!\n\nI can't read it if there's nothing to smell, Uplander. \n\nStill, it was nice of you to bring me a blank notebook.", objectives = "Bring the book back to Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
