quests[75831] = { id = 75831, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Barter Up", description = "Greetings, friend\n\nI've  heard you've come across something that I would be interested in. \n\nA very strong-smelling morsel, I'd like to see it. \n\nYou know, just to see if it's worth my time. \n\nYour extremely nice friend, \n\nPonzo", objectives = "Bring the Pungent Morsel to Ponzo in Loamm.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75833] = { id = 75833, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Report to the Trading Post", description = "<The glint of a distant object catches your eye. You suddenly remember that you have tender to collect for use at T&W Trading Post.>", progress = "Did you collect this month's tender?", completion = "Hope ya like this month's collection of new and exotic wares, {name}.", objectives = "Return to the Trading Post to collect your Trader's Tender from the Collector's Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75834] = { id = 75834, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Delver Mardei", objectives = "Defeat Delver Mardei in a Pet Battle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75835] = { id = 75835, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Do You Even Train?", objectives = "Defeat Trainer Orlogg in a Pet Battle", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75859] = { id = 75859, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: Sniffenseeking", description = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future.\n\nNow then, to business.\n\nOur niffen allies in Zaralek Cavern are always on the lookout for something new and exciting--or smelly. Join them on a dig through the many lost and forgotten caverns in their domain, and see what you find.\n\nWe await your return, {name}.", progress = "Do you bring news of your success?", completion = "My, my. What wondrous news! The Accord will be most pleased by your efforts. \n\nPlease accept this as a token of our gratitude.", objectives = "Travel to Zaralek Cavern and accompany Myrrit in Loamm on a dig underground. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75860] = { id = 75860, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: Researchers Under Fire", description = "Our allies once again seek your assistance as our efforts continue across the Isles. Words within the walls of Valdrakken whisper a resounding comfort knowing your efforts have helped shape our future.\n\nNow then, to business.\n\nResearchers of the Dragonscale Expedition are exploring the depths of Zaralek Cavern. They are asking for brave adventurers to help protect them from the many dangers in that area.\n\nWe await your return, {name}.", completion = "My, my. What wondrous news! The Accord will be most pleased by your efforts. \n\nPlease accept this as a token of our gratitude.", objectives = "Travel to Zaralek Cavern and protect the Researchers Under Fire. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75861] = { id = 75861, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aiding the Accord: Suffusion Camp", description = "Ash blows from the south. \n\nA dark bargain has been made, {name}, between the djaradin of the Zaqali and Fyrakk. Their forces are building... something.\n\nWe do not know what their goals are, but they have had no hesitation in displacing anyone and everything in their path. \n\nPlease, {name}, we need champions like you to undermine these villains and deprive them of their resources.\n\nWe await your return, {name}.", completion = "There is much we can learn from your efforts. What were they making? Well, that is a mystery for us to unravel later. \n\nPlease accept this as a token of our gratitude.", objectives = "Travel to a Suffusion Camp and loot a Secured Shipment. Continue your efforts in aiding the Valdrakken Accord and their allies throughout the Dragon Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75865] = { id = 75865, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Relic Rustler", description = "A group of mean, scaly uplanders moved in near the old titan ruins south of Loamm and started tearing the place apart.\n\nRude, but they're sure to have uncovered all sorts of ancient titan scraps. And that stuff is almost always magic in some way.\n\nGrab some and go see what Dustmonger Topuiz back in Loamm can make of it!", progress = "I can't wait to see what you uncover!", completion = "Amazing! These smell ancient... and just the right sort of tingly!", objectives = "Collect 8 Relic Shards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75867] = { id = 75867, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Link to the Past", description = "Okay, calibrations complete! Mine too, so I'll be able to see what you see.\n\nLet's head over to that telescope and we'll see what we see.", progress = "I wonder what we'll find?", completion = "Unfortunate for them, but perhaps an opportunity for us. Hmm....", objectives = "Observe the events from the past.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75868] = { id = 75868, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Window into the Future", description = "Those lenses are a wondrous integration of technology and arcane artifice. I'm sure we could learn much, and maybe even upgrade my own invention.\n\nBut first we'll need to find it. You're a dragonrider, right? Can you fly up and recover the lens?\n\nIt's possible the dreadsqualls still have it in one of their nests.", progress = "Did you recover the lens, {name}?", completion = "Success! \n\nI knew you were the right person for the job!", objectives = "Search Dreadsqualls nests to recover the lens.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75874] = { id = 75874, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Fly", description = "Zandalar is home to many pterrordaxes. One will accompany you into the skies.\n\nVisit Beast Master Kalatak at Dazar'alor in Zuldazar.", completion = "I'm glad you came. This pterrordax is unruly and yearns to see the world beyond Zandalar's shores. I cannot train such a beast.\n\nYou take it. May it bring you good fortune in your journey.", objectives = "Find Beast Master Kalatak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75877] = { id = 75877, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time to Fly", description = "Kul Tiras is home to many gryphons. One will accompany you into the skies.\n\nVisit Leila Stafford at the Tradewinds Market  in Boralus.", completion = "I'm glad you came. This young gryphon was left behind when the rest were sent for training. I didn't think I would ever see this day, but it is now ready to fly.\n\nWill you take it and fly around the world for me? May it bring you good fortune in your journey.", objectives = "Find Leila Stafford.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75885] = { id = 75885, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Get Rich Quick", description = "Uplander! I have a question for you. \n\nDo you want to wear an expensive hat like mine? Own the best snails in town? Enjoy the good life?\n\nIf the answer is yes, you're ready to make more wealth than you've ever dreamed of! Ponzo style!\n\nTogether we can both be rich! Of course I'm already rich, but you can be too!\n\nJust take these items I have here and show them around town. I'll cut you in for a share of the profits for every order you get.", progress = "Did you get any orders?", completion = "You did great! I even have a bonus for you.\n\nNow you can buy more things from me and sell as much as you want. Every sale you make makes us both richer.", objectives = "Get the citizens of Loamm to order some Ponzo's Cream and Glimmerogg Timeshare Vouchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75887] = { id = 75887, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fyrakk's Forces", description = "Champion, Fyrakk and his Primalist allies have struck a dark bargain with the djaradin. We have received word that their forces are assaulting the Dragon Isles in search of resources for some nefarious project.\n\nPlease, champion, find one of these Suffusion Camps and assist any of our allies you can find there.", completion = "Welcome Champion! Your aid would be appreciated.", objectives = "Journey to a Suffusion Camp.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75888] = { id = 75888, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Suffusion Camp", description = "Fyrakk has made a deal with the dragon hunting djaradin!\n\nTheir blacksmith, Igira, has sent her finest crafters under the aegis of Fyrakk's Primalists. They are gathering materials for the construction of... something. \n\nFind a way to access their Suffusion Crucibles and Molds. Keep what you find but we must learn more about what they are doing. The forces appear to require special wards to access the Crucibles and Molds. Start there.", progress = "What have you found in the Crucibles and Molds? \n\nAll of this shadowflame about makes my scales crawl.", completion = "Shadowflame! They are suffusing every ingredient and component with shadowflame!\n\nWhat are they crafting? It must be something far more dangerous than simply outfitting the army here.\n\nWell done, hero. We trust you to put those materials to better use than these beasts.", objectives = "Loot a Suffusion Crucible and a Suffusion Mold.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75890] = { id = 75890, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Clarion Call", description = "Good to see you, {name}. I have a message from someone called Arko'narin Starshade. It reads...\n\n\"As a protector of the kaldorei, I must ask for you to meet me near the embassy in Stormwind. Tyrande has called the Wardens to action, and Maiev Shadowsong herself requested your aid in this matter as well.\"\n\nArko'narin Starshade", completion = "It is an honor to meet you, {name}.", objectives = "Speak with Arko'narin Starshade near the Stormwind Embassy in Stormwind City.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75891] = { id = 75891, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ancient Curses", description = "Thank you for answering my call so quickly, {name}.\n\nDemonic corruption has seen a resurgence in Felwood recently. Tyrande sent out a contingent of Sentinels and one of her own priestesses to investigate the matter further. None have returned.\n\nTyrande asked the Wardens to look into the matter--and Maiev has asked for your assistance personally.\n\nWe need to make haste to Felwood, and see what Maiev has discovered.", progress = "May Elune guide us all to victory in this forsaken place.", completion = "I will fill you in on what we need to do, {name}.\n\nBut first, let me put my friend to rest.", objectives = "Meet Maiev Shadowsong in Felwood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75918] = { id = 75918, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Season", description = "No doubt you have seen the destruction that Fyrakk continues to leave in his wake.\n\nWhile others fight him directly, my troops and I have been serving as the eyes and ears of the green dragonflight. Although Fyrakk's actions may seem erratic, there are trends to his strategies.\n\nWe learned that he is to have a secret meeting with Vyranoth soon in Lunedane. This is a deviation from his recent tactics, and we need to know why.\n\nGiven the danger, we would value your aid. Meet me in Lunedane.", completion = "Keep to the shadows, {name}.\n\nLunedane is already crawling with Fyrakk's forces.", objectives = "Meet Shandris at Lunedane in the Ohn'ahran Plains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75919] = { id = 75919, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dousing the Wards", description = "Fyrakk and Vyranoth are already here. I spotted them near the overlook at the northeastern edge of Lunedane. Landing close to their location would reveal our presence, thus we are forced to begin our mission here. \n\nHowever, the bridge connecting this area to the overlook has been protected with fire magic. We will not be able to break through it.\n\nFyrakk's Primalist allies appear to be maintaining the fire using wards set up around this area. \n\nIf we destroy the wards, the fire should subside.", progress = "We need to bring that barrier down so we can get closer to the Incarnates. We cannot hear them from this far away.", completion = "Destroying those stones appears to have extinguished the fire magic protecting the bridge.\n\nThough I cannot be certain how long it will stay that way. It would be best to move swiftly.", objectives = "Destroy 4 Warding Firestones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75920] = { id = 75920, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eyes of Fire", description = "This area is swarming with far more Primalists than I expected. Fyrakk does not generally travel with guards, so I doubt the Primalists are here to accompany him.\n\nThey seem to be trying to establish a foothold here. But why? \n\nPerhaps whatever the Incarnates are discussing will answer that question.\n\nIn the meantime, let us thin out the Primalists guarding this area. We cannot risk having them in full force behind us as we cross the bridge.", progress = "We will need to work quickly. We cannot risk drawing the attention of the Incarnates.", completion = "<Shandris looks back at the bodies of the druids. She appears bewildered, but there is pain in her eyes.>\n\nDruids of the Flame? \n\nFyrakk has conscripted them into his service?\n\nWhy would any night elf agree to this...?", objectives = "Kill 8 Burning Flamespeakers or Blazing Overseers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75921] = { id = 75921, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Flames", description = "Druids of the Flame...\n\n<Shandris frowns deeply, eyes shut as she holds back her anger.>\n\nTo think that they still exist. That any of our people would join Fyrakk and his--\n\n<She stops, releases a heavy breath, and continues.>\n\nWe have a mission to complete.\n\nWe need to cross the bridge to get close enough to the Incarnates that we can overhear their conversation. I will shroud us so that we can move between the elementals still guarding the way forward.", progress = "We need be as close to the Incarnates as we can.\n\nWe cannot afford to miss a single word of their conversation.", completion = "This is as close as we can get without revealing ourselves.", objectives = "Collect 4 Smoldering Blossoms while crossing the bridge towards Fyrakk and Vyranoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75922] = { id = 75922, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inflammatory Information", description = "<Shandris whispers to you.>\n\nDo you see that up ahead? The Druids of the Flame have captured what appears to be a keeper--a guardian of nature, sacred to our people. If their power is already enough to...\n\n<Shandris shakes her head, then gestures at the dense shrubbery nearby.>\n\nStay hidden with me and we will listen to the Incarnates, and perhaps discern what the druids intend to do with the keeper.", progress = "I will hold off any reinforcements that come. Deal with the keeper!", completion = "I had feared what we might learn today, but this...\n\n<Shandris tightens her grip on her bow to steady herself.>\n\nThis is beyond anything we could have prepared ourselves for.", objectives = "Eavesdrop on Fyrakk and Vyranoth.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75923] = { id = 75923, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Raise the Alarm", description = "So the Druids of the Flame have allied with Fyrakk to help him invade the Emerald Dream.\n\nThey were able to turn that keeper to the flame with hardly any effort. Fyrakk must be bolstering their power, perhaps as payment for their aid in accessing the Dream.\n\nWe need to mobilize troops immediately to find every Druid of the Flame on the Dragon Isles and stop them.\n\nGo to Captain Drine in Valdrakken and alert her. She will dispatch the drakonid.\n\nI will go to Merithra and handle things here.", completion = "We have to trust Alexstrasza for now.", objectives = "Deliver your report to Captain Drine at the Seat of the Aspects in Valdrakken.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75932] = { id = 75932, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Loamm Niffen" }
quests[75935] = { id = 75935, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Time, Signature", description = "Oh good, an adventurer. You've heard of Pedgi, I presume? The composer?\n\nNo? Well, don't tell him that.\n\nWe were traveling to research his next song, when we stumbled upon a dragon named Tempo. Pedgi is now convinced they're the only one who can help us. \n\nYes, because of the name. That's really all it takes for him.\n\nBut Tempo here is, understandably, too busy to help us. Could you talk to them? See if we can help clear their schedule?", progress = "Yes, he's always like this. But he pays well and I get to travel.", completion = "Thanks for talking to Tempo.\n\nPedgi can be temperamental, but his heart is in the right place. Most of the time.", objectives = "See if Tempo would be willing to help Pedgi with his music.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75936] = { id = 75936, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slimy Yet Satisfying", description = "<A worm. You know someone who might love this.>", progress = "<Marie Shellie drips slime.>", completion = "<Marie Shellie wiggles her antennae, dripping goo on you in the process.>", objectives = "Bring 1 Wriggling Worm to Marie Shellie in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75937] = { id = 75937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "No Time Like The Present", description = "Emberthal arrived while you were in the field. She and her allies are surveying the area from the cliffs above. \n\nIt would be wise to check in with her, I think. We would not want her to attempt taking the Reach alone.", objectives = "Meet with Emberthal above the cliffs of Morqut Village.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75938] = { id = 75938, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Test" }
quests[75949] = { id = 75949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Downbeat Data", description = "You say that Tempo mentioned objects from other timelines?\n\nI have a device used for syncing melodies. Strangely enough, it seems to have the same effect on timelines in this town. Perhaps a side effect of the chaotic temporal energies here?\n\nI've upgraded Pedgi's glasses to allow him to observe the rhythms of the world. They may make it easier to find mis-timed entities. Ask if you can borrow them.", progress = "Have you found any mis-timed entities?", completion = "Looks like the mis-timed objects are back in their proper place. One less thing for Tempo to worry about.\n\nHmm... Interesting data here. Perhaps it will come in handy later.\n\nApologies that Pedgi hasn't been much help. Probably best to muster up his resolve. This is his song to compose, after all.", objectives = "Use Melly's device near objects from other timelines. Pedgi's sunglasses will make them easier to find.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75950] = { id = 75950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exemplar of Justice: Hadwin", description = "We've been out here for a good bit of time. Time enough for me to watch the gnolls around here.\n\nGnolls are usually a nuisance, but the decay gnolls around Brackenhide Hollow...\n\nThe decay doesn't just warp their bodies. It warps their minds too.\n\nDecaymonger Rotpaw is the worst of them. She's indiscriminate in who or what she spreads her decay to: the unwilling of her people, travelers, animals, children...\n\nIf there's any justice in this world, she should be taken down.", completion = "Perhaps I bit off a bit more than I could chew... But with your help, Rotpaw and her ilk paid for their crimes.", objectives = "Help Hadwin defeat Decaymonger Rotpaw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75951] = { id = 75951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exemplar of Order: Talthis", description = "I know why Travard chose this area for our training. The decay here is... chaotic and disordered.\n\nThings that Tyr and the titans are not! \n\nThe nearby gnolls revel in the decay. Revolting.\n\nThey have taken over territory that was once occupied by the proud, noble, and civil tuskarr.\n\nThe tuskarr have asked that relics they had to abandon are returned to them. Please help me fight the gnolls and retrieve the relics so the tuskarr can continue their rituals in Iskaara.", progress = "The gnolls had no right to those relics. They belong to the tuskarr.", completion = "I am glad that we could restore these relics to the tuskarr. It feels good to impose some semblance of order on the chaos of decay.", objectives = "Bring Talthis 5 Tuskarr relics.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75952] = { id = 75952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exemplar of Sacrifice: Nolaki", description = "Much is said about how decay spreads through the air and ground. But it also spreads through the water. \n\nSlimes that live in the rivers and streams ooze pestilence. The water is toxic with it. But if we wade in and kill the big one, the poison in the water will diminish.\n\nIt may poison me in the process, but I am going to kill one if it's the last thing I do. This place needs a purging. \n\nAre you with me, {name}?", completion = "Thank you for stopping those smaller slimes, {name}. I was able to kill the big one, but I would still be there if it weren't for your aid.", objectives = "Help Nolaki defeat a massive slime.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75953] = { id = 75953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Exemplar of Compassion: Valunei", description = "It makes my heart ache to see what the decay has done to some of the wildlife here...\n\nI cannot save all the creatures that live around Brackenhide Hollow, but I wish for my trial to at least save some.\n\nIn a cave to the west, there is a family of bears that has recently been corrupted. I believe I can fight my way there and heal them. Will you help me, {name}?", completion = "Tyr's compassion for the vrykul inspires me. I think he would have compassion for animals too, do you not? They suffer and feel pain just as you or I would... \n\nThank you for helping me save those bears. Even a little compassion goes a long way.", objectives = "Protect Valunei from decay gnolls.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75954] = { id = 75954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stormsunder Crater Circuit - Challenge", description = "Fly through the checkpoint rings marking the course.", objectives = "Glide through the rings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
