quests[75966] = { id = 75966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Compose Yourself", description = "I promise he's not always like this. But he is, often, like this.\n\nUsually it takes him a few days to come out of his funk, but we don't have that sort of time. The commission he got to write this song won't last forever.\n\nMaybe we can speed up the process. Could you help raise Pedgi's confidence?", progress = "Hmm...", completion = "I found some trouble!", objectives = "Raise Pedgi's confidence.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75970] = { id = 75970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracked Through Time", description = "A Timewalker spotted a bear cub who stumbled into our present time. She was so frightened she ran off before he could catch her!\n\nCan you find the poor thing? You'll need to calm her down before she'll follow you.\n\nBring her back here and I'll open a temporal portal to take her home.", progress = "That cub must be so scared, all alone and in a strange place. We need to get her back home!", completion = "Surprised by who that little bear turns out to be? Just goes to show you that even the smallest creatures can have a big impact!", objectives = "Rescue a Time-Lost Cub and return her to her proper time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[75971] = { id = 75971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Squeaky Toy of Time and Space", description = "We have detected another time anomaly. A strange object that even we cannot understand the significance of.\n\nThis artifact must be returned before it does irreparable damage to the true timeline and the world as we know it.\n\nReturn here once you have recovered the artifact. I will open a portal so you may return it to its proper place.", progress = "All of our fates depend on returning that artifact to its proper time.", completion = "Thank you, champion. You have helped save Azeroth once again. I shudder to think what would have happened, were you not here to intervene...", objectives = "Find the Time-Displaced Toy and return it to its proper time.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
