quests[76025] = { id = 76025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", completion = "We won't forget what you've done for us!", objectives = "Talk to Mimuup in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76026] = { id = 76026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Surveying the Tower", description = "Get a load of those rock formations! Surveying doesn't get much better than this.\n\nThis tower has been here for ages. The black dragonflight used it for some seriously dark stuff, but that's not why we're here. After the dragons left, a troupe of niffen bandits took shelter in the ruins and robbed the place blind. But they left a bunch of trash everywhere.\n\nImagine what we could learn about the niffen from that trash once we get digging!", completion = "<Roska lets out an uproarious bout of laughter.>\n\nOh, now that one's got to have some kind of crazy story behind it!", objectives = "Speak with Roska to start the dig, then excavate artifacts from around the tower.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76027] = { id = 76027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flapping and Screaming" }
quests[76028] = { id = 76028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", completion = "Thanks so much for all of your help!", objectives = "Talk to Mimuup in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76029] = { id = 76029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", completion = "Thanks so much for all your help around here!", objectives = "Talk to Mimuup in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76030] = { id = 76030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Airborne Winding", description = "Well hello there!\n\nWord around here is that we've got your continued support--so we got a little something for you. Meet me in Loamm so I can hand it over!\n\nBest,\nHarlowe Marl", completion = "We're lucky to have you around!", objectives = "Talk to Harlowe Marl in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76031] = { id = 76031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dragon Isles Supplies", completion = "Honestly, we're forever grateful. Thank you!", objectives = "Talk to Mimuup in Loamm.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[76032] = { id = 76032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hidden in the Midden", description = "<This dragon statue is similar to others found in the region but has been covered in paint.\n\nGoogly eyes, stink lines, whiskers, and all manner of other rude drawings decorate the otherwise-imposing stone. The paint looks old and is flaking in places but is not as old as the statue itself.\n\nRoska will want to have a look at this!>", progress = "Nothing like volcanic rock, eh {name}? Never know what you'll find!", completion = "I'll tell you what, these niffen bandits had a sense of humor!", objectives = "Carefully excavate the defaced dragon statue.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
